+use lazy_static::lazy_static;
+use slog::{info, warn, Logger};
+use std::collections::HashMap;
+use std::sync::Arc;
+use tokio::sync::Mutex;
+use tokio_vsock::{VsockAddr, VsockListener, VsockStream};
+
+lazy_static! {
+    pub static ref PASSFD_STREAMS: Arc<Mutex<HashMap<u32, VsockStream>>> =
+        Arc::new(Mutex::new(HashMap::new()));
+    pub static ref PASSFD_WAITERS: Arc<Mutex<HashMap<u32, tokio::sync::oneshot::Sender<()>>>> =
+        Arc::new(Mutex::new(HashMap::new()));
+}
+
+pub async fn start_passfd_listener(logger: Logger) -> anyhow::Result<()> {
+    let addr = VsockAddr::new(libc::VMADDR_CID_ANY, protocols::PASSFD_LISTENER_PORT);
+    let listener = VsockListener::bind(addr)?;
+
+    info!(
+        logger,
+        "Listening for passfd connections on port {}",
+        protocols::PASSFD_LISTENER_PORT
+    );
+
+    tokio::spawn(async move {
+        loop {
+            match listener.accept().await {
+                Ok((stream, addr)) => {
+                    let port = addr.port();
+                    // Insert first to minimize race window
+                    let mut streams = PASSFD_STREAMS.lock().await;
+                    streams.insert(port, stream);
+                    drop(streams);
+
+                    let mut waiters = PASSFD_WAITERS.lock().await;
+                    if let Some(tx) = waiters.remove(&port) {
+                        let _ = tx.send(());
+                    }
