+lazy_static! {
+    pub static ref PASSFD_STREAMS: Arc<Mutex<HashMap<u32, VsockStream>>> =
+        Arc::new(Mutex::new(HashMap::new()));
+    pub static ref PASSFD_WAITERS: Arc<Mutex<HashMap<u32, tokio::sync::oneshot::Sender<()>>>> =
