+
+pub async fn start_passfd_listener(logger: Logger) -> anyhow::Result<()> {
+    let addr = VsockAddr::new(libc::VMADDR_CID_ANY, protocols::PASSFD_LISTENER_PORT);
+    let listener = VsockListener::bind(addr)?;
+
+    info!(
+        logger,
+        "Listening for passfd connections on port {}",
+        protocols::PASSFD_LISTENER_PORT
+    );
+
+    tokio::spawn(async move {
+        loop {
+            match listener.accept().await {
+                Ok((stream, addr)) => {
+                    let port = addr.port();
+                    // Insert first to minimize race window
+                    let mut streams = PASSFD_STREAMS.lock().await;
+                    streams.insert(port, stream);
+                    drop(streams);
