+                    drop(waiters);
+
+                    info!(logger, "Accepted passfd connection on port {}", port);
+                }
+                Err(e) => {
+                    warn!(logger, "Error accepting passfd connection: {:?}", e);
+                }
+            }
+        }
+    });
