+
+type terminalOutputWriter struct {
+	stream      terminalStreamSender
+	sendMu      *sync.Mutex
+	lastActive  *int64
+	requestID   string
+	sessionID   string
+	sandboxID   string
+	containerID string
+}
+
+func (w *terminalOutputWriter) Write(data []byte) (int, error) {
+	if len(data) == 0 {
+		return 0, nil
+	}
+	terminalMarkActive(w.lastActive)
+	cp := append([]byte(nil), data...)
+	err := terminalSend(w.stream, w.sendMu, &cubeboxv1.TerminalFrame{
+		Type:        cubeboxv1.TerminalFrame_OUTPUT,
+		RequestID:   w.requestID,
+		SessionId:   w.sessionID,
+		SandboxId:   w.sandboxID,
+		ContainerId: w.containerID,
+		Data:        cp,
+	})
+	if err != nil {
+		return 0, err
+	}
+	return len(data), nil
+}
+
+func terminalMarkActive(lastActive *int64) {
+	atomic.StoreInt64(lastActive, time.Now().UnixNano())
+}
+
+func terminalIdleExpired(lastActive int64, now time.Time, timeout time.Duration) bool {
+	return now.Sub(time.Unix(0, lastActive)) > timeout
+}
+
+func terminalFrameRefreshesIdle(frame *cubeboxv1.TerminalFrame) bool {
+	return frame.GetType() == cubeboxv1.TerminalFrame_INPUT && len(frame.GetData()) > 0
+}
+
+func terminalStreamClosedCleanly(err error) bool {
+	return errors.Is(err, io.EOF) || grpcstatus.Code(err) == codes.Canceled || grpcstatus.Code(err) == codes.OK
+}
+
+func terminalSend(stream terminalStreamSender, sendMu *sync.Mutex, frame *cubeboxv1.TerminalFrame) error {
+	sendMu.Lock()
+	defer sendMu.Unlock()
+	return stream.Send(frame)
+}
