+		return nil, nil, "", fmt.Errorf("sandbox lookup failed")
+	}
+	if info.Ret.RetCode != int(errorcode.ErrorCode_Success) {
+		return nil, nil, "", fmt.Errorf("%s", info.Ret.RetMsg)
+	}
+	if len(info.Data) == 0 {
+		return nil, nil, "", fmt.Errorf("sandbox not found")
+	}
+	target := info.Data[0]
+	if target.Status != terminalContainerRunning {
+		return nil, nil, "", fmt.Errorf("sandbox is not running")
+	}
+
+	var selected *types.ContainerInfo
+	for _, c := range target.Containers {
+		if containerID != "" && c.ContainerID == containerID {
+			selected = c
+			break
