+func bridgeWebsocketToTerminal(conn *websocket.Conn, stream *cubelet.TerminalStream, requestID, sessionID, sandboxID, containerID string, errCh chan<- error) {
+	for {
+		messageType, data, err := conn.ReadMessage()
+		if err != nil {
+			_ = stream.Send(&cubebox.TerminalFrame{Type: cubebox.TerminalFrame_CLOSE, RequestID: requestID, SessionId: sessionID, SandboxId: sandboxID, ContainerId: containerID})
