+				sendErr = stream.Send(&cubebox.TerminalFrame{Type: cubebox.TerminalFrame_CLOSE, RequestID: requestID, SessionId: sessionID, SandboxId: sandboxID, ContainerId: containerID})
+				errCh <- sendErr
+				return
+			}
+			if sendErr != nil {
+				errCh <- sendErr
+				return
+			}
+		case websocket.CloseMessage:
+			_ = stream.Send(&cubebox.TerminalFrame{Type: cubebox.TerminalFrame_CLOSE, RequestID: requestID, SessionId: sessionID, SandboxId: sandboxID, ContainerId: containerID})
+			errCh <- nil
+			return
+		}
+	}
